CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_BUDGET_ACTUAL_MONTH_ACCOUNT
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_BUDGET_ACTUAL at grain Date.FiscalYear, Date.MonthName, Date.Quarter, GLAccount.AccountCode, GLAccount.AccountName, Date.MonthNumber; covers 57.97% of weighted demand (7 clusters); est. 300,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       d1.QUARTER,
       g2.ACCOUNT_CODE,
       g2.ACCOUNT_NAME,
       d1.MONTH_NUMBER,
       SUM(f.ACTUAL_AMOUNT) AS ACTUAL_AMOUNT,
       SUM(f.BUDGET_AMOUNT) AS BUDGET_AMOUNT,
       SUM(f.VARIANCE_AMOUNT) AS VARIANCE_AMOUNT,
       SUM(f.VARIANCE_PCT) AS VARIANCE_PCT_SUM,
       COUNT(f.VARIANCE_PCT) AS VARIANCE_PCT_COUNT,
       COUNT(*) AS BUDGET_ACTUAL_COUNT
FROM CORE.FCT_BUDGET_ACTUAL f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_GL_ACCOUNT g2 ON f.GL_ACCOUNT_ID = g2.GL_ACCOUNT_ID
GROUP BY ALL;

